def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    sweater_patches = image_patch.find("sweater")

    if not man_patches or not sweater_patches:
        return image_patch

    man_sweater_pairs = []
    for man in man_patches:
        for sweater in sweater_patches:
            if man.overlaps_with(sweater.left, sweater.lower, sweater.right, sweater.upper):
                man_sweater_pairs.append((man, sweater))

    if not man_sweater_pairs:
        return image_patch

    man_sweater_pairs.sort(key=lambda pair: abs(pair[0].horizontal_center - pair[1].horizontal_center))

    return man_sweater_pairs[0][0]

